        setValue(L.DESC_COMMAND_GET_BOOK_INFO_LLM, "Die Übersicht über das Buch: Name, Beschreibung, Sprache, Erzählperspektive, Zeitform, Stil, das Modell und das Protokoll, wie viele Abschnitte, Wörter und Tokens der aktive Zweig und das ganze Buch haben, die Tags und die Sicherungsstrategie. Nur lesend. Rufe es zuerst auf, um zu erfahren, was das Buch ist.");
        setValue(L.DESC_COMMAND_GET_BOOK_INFO_RETURN, "JSON mit den Einstellungen und den Summen des Buchs");
        setValue(L.DESC_COMMAND_LIST_PARTS, "Listet die Abschnitte eines Zweigs mit Position, Größe, Varianten und einer Vorschau auf.");
        setValue(L.DESC_COMMAND_LIST_PARTS_LLM, "Listet die Abschnitte eines Zweigs auf, vom ersten Abschnitt der Geschichte an: Position, Anzahl der Varianten (Alternativen), Wörter, Tokens, der Zustand ihrer Zusammenfassung (keine, gültig, veraltet) und eine kurze Vorschau. Seitenweise: offset und limit. Ein Abschnitt wird über sein Handle angegeben (das „handle“ der Listen; es ändert sich nicht, wenn Abschnitte hinzugefügt oder gelöscht werden, bevorzuge es also) oder über seine Position in einem Zweig (der erste Abschnitt der Geschichte ist 1); der Zweig ist der aktive, sofern nicht das Handle eines Abschnitts darauf oder eine Zweignummer aus list-branches angegeben wird. Nur lesend. Optionen sind positionsbezogen und optional, in der aufgeführten Reihenfolge. Jede Zeile hat außerdem ihr „handle“: Es ändert sich nicht, wenn etwas hinzugefügt oder gelöscht wird, und die Befehle, die das Buch ändern, nehmen es entgegen.");
        setValue(L.DESC_COMMAND_LIST_PARTS_RETURN, "JSON mit den Abschnitten der Seite: Position, Varianten, Wörter, Tokens, Zusammenfassungszustand, Vorschau");
        setValue(L.DESC_COMMAND_GET_PART, "Liest den Text eines Abschnitts oder eines seiner anderen Felder in Ausschnitten.");
        setValue(L.DESC_COMMAND_GET_PART_LLM, "Liest einen Abschnitt: einen Ausschnitt seines Textes (offset, length; die Antwort nennt die Gesamtlänge und ob mehr folgt) und die Daten, aus denen er entstanden ist (Anweisungen, Szene, Erzählperspektive, anwesende Figuren), seine Größe und das verwendete Modell. Die Option field liest stattdessen: instructions, scene, pov, present oder reasoning. Ein Abschnitt wird über sein Handle angegeben (das „handle“ der Listen; es ändert sich nicht, wenn Abschnitte hinzugefügt oder gelöscht werden, bevorzuge es also) oder über seine Position in einem Zweig (der erste Abschnitt der Geschichte ist 1); der Zweig ist der aktive, sofern nicht das Handle eines Abschnitts darauf oder eine Zweignummer aus list-branches angegeben wird. Nur lesend. Optionen sind positionsbezogen und optional, in der aufgeführten Reihenfolge.");
        setValue(L.DESC_COMMAND_GET_PART_RETURN, "JSON mit einem Textausschnitt, seinem Offset und der Gesamtlänge sowie den Daten des Abschnitts");
        setValue(L.DESC_COMMAND_LIST_SWIPES, "Listet die Alternativen (Varianten) eines Abschnitts auf.");
        setValue(L.DESC_COMMAND_LIST_SWIPES_LLM, "Listet die Varianten eines Abschnitts auf: die Alternativen, die für dieselbe Stelle der Geschichte generiert wurden. Jede hat ihre Nummer, ob sie die angezeigte ist, die Wörter, eine Vorschau und die Zweignummer, die sie zeigt, um sie mit get-part zu lesen. Ein Abschnitt wird über sein Handle angegeben (das „handle“ der Listen; es ändert sich nicht, wenn Abschnitte hinzugefügt oder gelöscht werden, bevorzuge es also) oder über seine Position in einem Zweig (der erste Abschnitt der Geschichte ist 1); der Zweig ist der aktive, sofern nicht das Handle eines Abschnitts darauf oder eine Zweignummer aus list-branches angegeben wird. Nur lesend. Optionen sind positionsbezogen und optional, in der aufgeführten Reihenfolge. Jede Zeile hat außerdem ihr „handle“: Es ändert sich nicht, wenn etwas hinzugefügt oder gelöscht wird, und die Befehle, die das Buch ändern, nehmen es entgegen.");
        setValue(L.DESC_COMMAND_LIST_SWIPES_RETURN, "JSON mit den Varianten: Nummer, angezeigt, Wörter, Vorschau, Zweig");
        setValue(L.DESC_COMMAND_LIST_BRANCHES, "Listet die Zweige des Buchs mit ihren Nummern auf.");
        setValue(L.DESC_COMMAND_LIST_BRANCHES_LLM, "Listet die Zweige der Geschichte auf, wobei ein Zweig ein Weg vom ersten Abschnitt zu einem der Enden ist. Jeder hat seine Nummer (die als Zweig an andere Befehle übergeben wird; die Nummern folgen der Erstellung der Enden und ändern sich, wenn ein Zweig hinzugefügt oder gelöscht wird), ob er der aktive ist, Abschnitte, Wörter, die Position, nach der er sich von den anderen trennt, und eine Vorschau seines Endes. Seitenweise: offset und limit. Nur lesend. Optionen sind positionsbezogen und optional, in der aufgeführten Reihenfolge. Jede Zeile hat außerdem ihr „handle“: Es ändert sich nicht, wenn etwas hinzugefügt oder gelöscht wird, und die Befehle, die das Buch ändern, nehmen es entgegen.");
        setValue(L.DESC_COMMAND_LIST_BRANCHES_RETURN, "JSON mit den Zweigen: number, active, parts, words, forkPosition, created, endPreview");
        setValue(L.DESC_COMMAND_GET_PART_METRICS, "Zeigt die Tokens, Zeiten, das Modell und das Protokoll eines Abschnitts.");
        setValue(L.DESC_COMMAND_GET_PART_METRICS_LLM, "Die Zahlen eines generierten Abschnitts: seine Tokens und Wörter, Prompt- und Reasoning-Tokens, das Modell und das Protokoll, die ihn geschrieben haben, die Zeit bis zum ersten Token und die Zeit des Reasonings. Ein Abschnitt wird über sein Handle angegeben (das „handle“ der Listen; es ändert sich nicht, wenn Abschnitte hinzugefügt oder gelöscht werden, bevorzuge es also) oder über seine Position in einem Zweig (der erste Abschnitt der Geschichte ist 1); der Zweig ist der aktive, sofern nicht das Handle eines Abschnitts darauf oder eine Zweignummer aus list-branches angegeben wird. Nur lesend. Optionen sind positionsbezogen und optional, in der aufgeführten Reihenfolge.");
        setValue(L.DESC_COMMAND_GET_PART_METRICS_RETURN, "JSON mit den Kennzahlen des Abschnitts");
        setValue(L.DESC_COMMAND_SHOW_PROMPT, "Zeigt den Prompt, aus dem ein generierter Abschnitt entstanden ist.");
        setValue(L.DESC_COMMAND_SHOW_PROMPT_LLM, "Der Prompt, so wie er beim Generieren des Abschnitts gesendet wurde, mit ihm gespeichert: ein Ausschnitt seines Textes (offset, length), die Tokens, die er hatte, die Aufschlüsselung der Tokens nach Abschnitt und die hinzugefügte Hintergrund-Lore. Abschnitte, die nicht generiert wurden oder generiert wurden, bevor der Prompt gespeichert wurde, haben keinen. Ein Abschnitt wird über sein Handle angegeben (das „handle“ der Listen; es ändert sich nicht, wenn Abschnitte hinzugefügt oder gelöscht werden, bevorzuge es also) oder über seine Position in einem Zweig (der erste Abschnitt der Geschichte ist 1); der Zweig ist der aktive, sofern nicht das Handle eines Abschnitts darauf oder eine Zweignummer aus list-branches angegeben wird. Nur lesend. Optionen sind positionsbezogen und optional, in der aufgeführten Reihenfolge.");
        setValue(L.DESC_COMMAND_SHOW_PROMPT_RETURN, "JSON mit einem Ausschnitt des Prompts, seinen Tokens und der Aufschlüsselung der Tokens");
        setValue(L.DESC_COMMAND_SEARCH_PARTS, "Durchsucht die Abschnitte aller Zweige nach Wörtern.");
        setValue(L.DESC_COMMAND_SEARCH_PARTS_LLM, "Volltextsuche über die Abschnitte aller Zweige: Jedes Wort der Anfrage muss im Abschnitt vorkommen (eine Wortgruppe in doppelten Anführungszeichen, * steht für beliebige Zeichen). Jeder Treffer enthält die Position des Abschnitts, die Zweignummer, wenn er nicht im aktiven Zweig liegt, und einen Textausschnitt um den Treffer. Mit includeVersions werden auch die älteren Versionen der Abschnitte (ihr Verlauf) durchsucht: Ein Abschnitt, der nur über eine davon gefunden wird, hat eine „version“ mit ihrer ID, Zeit und Quelle, und der Ausschnitt stammt aus dieser Version. Nur lesend. Optionen sind positionsbezogen und optional, in der aufgeführten Reihenfolge. Jede Zeile hat außerdem ihr „handle“: Es ändert sich nicht, wenn etwas hinzugefügt oder gelöscht wird, und die Befehle, die das Buch ändern, nehmen es entgegen.");
        setValue(L.DESC_COMMAND_SEARCH_PARTS_RETURN, "JSON mit den Treffern: Position, Zweig und Ausschnitt");
        setValue(L.DESC_COMMAND_FIND_OCCURRENCES, "Zählt, wo Namen oder Wörter in der Geschichte vorkommen.");
        setValue(L.DESC_COMMAND_FIND_OCCURRENCES_LLM, "Kontinuitätsprüfung, die im Code und nicht in Tokens erledigt wird: für jeden Begriff (ein Name und seine Varianten), in wie vielen Abschnitten und wie oft er vorkommt, und die ersten Abschnitte mit einem Ausschnitt. Durchsucht den aktiven Zweig, sofern allBranches nicht true ist, und auch die Zusammenfassungen, wenn summaries true ist. Optionen in dieser Reihenfolge: regex (false), caseSensitive (false), summaries (false), allBranches (false), limit (die meisten aufgelisteten Abschnitte je Begriff, 50). Nur lesend. Jede Zeile hat außerdem ihr „handle“: Es ändert sich nicht, wenn etwas hinzugefügt oder gelöscht wird, und die Befehle, die das Buch ändern, nehmen es entgegen.");
        setValue(L.DESC_COMMAND_FIND_OCCURRENCES_RETURN, "JSON je Begriff: die gefundenen Abschnitte und Vorkommen und wo");
        setValue(L.DESC_COMMAND_COMPARE_PARTS, "Zeigt die Sätze, die sich zwischen zwei Abschnitten unterscheiden.");
        setValue(L.DESC_COMMAND_COMPARE_PARTS_LLM, "Vergleicht zwei Abschnitte Satz für Satz und listet die Sätze auf, die nur einer von beiden hat (- vom ersten, + vom zweiten), bis zu 200. Um zwei Varianten zu vergleichen, gib ihre Positionen (dieselbe) und ihre Zweignummern aus list-swipes an. Als zweite Position vergleicht 0 den ersten Abschnitt mit dem Text, den das Modell zuerst erzeugt hat, um zu sehen, was der Autor bearbeitet hat. Positionen beziehen sich auf einen Zweig (den aktiven, sofern keine Zweignummer angegeben ist). Nur lesend. Optionen sind positionsbezogen und optional, in der aufgeführten Reihenfolge.");
        setValue(L.DESC_COMMAND_COMPARE_PARTS_RETURN, "JSON mit den Anzahlen und den Sätzen, die sich unterscheiden");
        setValue(L.DESC_COMMAND_COUNT_TOKENS, "Zählt die Tokens und Wörter eines Textes oder eines Abschnitts.");
        setValue(L.DESC_COMMAND_COUNT_TOKENS_LLM, "Zählt die Tokens eines Textes oder des Textes eines Abschnitts, wenn der Text das Handle des Abschnitts ist (oder ein nach Position und Zweig angegebener Abschnitt), mit dem Tokenizer des Modells des Buchs (einem generischen, wenn es keines hat), sowie seine Wörter und Zeichen. Verwende es, um zu planen, wie viel Text hineinpasst. Nur lesend.");
        setValue(L.DESC_COMMAND_COUNT_TOKENS_RETURN, "JSON mit den Tokens, Wörtern und Zeichen");
        setValue(L.DESC_COMMAND_LIST_SUMMARIES, "Listet die Zusammenfassungen eines Zweigs auf und ob sie gültig sind.");
        setValue(L.DESC_COMMAND_LIST_SUMMARIES_LLM, "Listet die Zusammenfassungen auf, die die Generierung in einem Zweig verwendet, von der ersten an: die Position des Abschnitts, der sie hat, die Abschnitte, die sie abdeckt, normale oder Metazusammenfassung, Tokens, ob sie die Geschichte noch beschreibt (gültig) und wie viele Zusammenfassungen eine Metazusammenfassung ersetzt, dann wie viele Abschnitte am Ende keine Zusammenfassung haben. Nur lesend. Optionen sind positionsbezogen und optional, in der aufgeführten Reihenfolge. Jede Zeile hat außerdem ihr „handle“: Es ändert sich nicht, wenn etwas hinzugefügt oder gelöscht wird, und die Befehle, die das Buch ändern, nehmen es entgegen.");
        setValue(L.DESC_COMMAND_LIST_SUMMARIES_RETURN, "JSON mit den Zusammenfassungen: position, covers, type, tokens, valid");
        setValue(L.DESC_COMMAND_GET_SUMMARY, "Liest die Zusammenfassung eines Abschnitts.");
        setValue(L.DESC_COMMAND_GET_SUMMARY_LLM, "Die an einem Abschnitt gespeicherte Zusammenfassung: ihr Text, ihre Tokens, ihre Art und ob sie die Geschichte noch beschreibt. Eine Zusammenfassung wird am letzten der von ihr abgedeckten Abschnitte gespeichert, daher haben die meisten Abschnitte keine (hasSummary false). Ein Abschnitt wird über sein Handle angegeben (das „handle“ der Listen; es ändert sich nicht, wenn Abschnitte hinzugefügt oder gelöscht werden, bevorzuge es also) oder über seine Position in einem Zweig (der erste Abschnitt der Geschichte ist 1); der Zweig ist der aktive, sofern nicht das Handle eines Abschnitts darauf oder eine Zweignummer aus list-branches angegeben wird. Nur lesend. Optionen sind positionsbezogen und optional, in der aufgeführten Reihenfolge.");
        setValue(L.DESC_COMMAND_GET_SUMMARY_RETURN, "JSON mit der Zusammenfassung des Abschnitts");
        setValue(L.DESC_COMMAND_CHECK_SUMMARIES, "Findet die Zusammenfassungen, die nicht mehr zur Geschichte passen.");
        setValue(L.DESC_COMMAND_CHECK_SUMMARIES_LLM, "Findet die veralteten Zusammenfassungen eines Zweigs (die Generierung verwirft sie): wo sie sind und welche Abschnitte sie abdecken. Nur lesend. Optionen sind positionsbezogen und optional, in der aufgeführten Reihenfolge. Jede Zeile hat außerdem ihr „handle“: Es ändert sich nicht, wenn etwas hinzugefügt oder gelöscht wird, und die Befehle, die das Buch ändern, nehmen es entgegen.");
        setValue(L.DESC_COMMAND_CHECK_SUMMARIES_RETURN, "JSON mit der Anzahl der Zusammenfassungen und den veralteten mit den Abschnitten, die sie abdecken");
        setValue(L.DESC_COMMAND_GET_TEMPLATE_VARIABLES, "Zeigt die Vorlagenvariablen des Buchs oder eines Abschnitts.");
        setValue(L.DESC_COMMAND_GET_TEMPLATE_VARIABLES_LLM, "Die Variablen, die Prompt-Vorlagen mit setvar setzen: die globalen des Buchs (scope global) oder die an einem Abschnitt, die seinem Zweig folgen (scope part; der letzte Abschnitt des Zweigs, wenn keine Position angegeben ist). Ein Abschnitt wird über sein Handle angegeben (das „handle“ der Listen; es ändert sich nicht, wenn Abschnitte hinzugefügt oder gelöscht werden, bevorzuge es also) oder über seine Position in einem Zweig (der erste Abschnitt der Geschichte ist 1); der Zweig ist der aktive, sofern nicht das Handle eines Abschnitts darauf oder eine Zweignummer aus list-branches angegeben wird. Nur lesend. Optionen sind positionsbezogen und optional, in der aufgeführten Reihenfolge.");
        setValue(L.DESC_COMMAND_GET_TEMPLATE_VARIABLES_RETURN, "JSON mit den Variablen und ihren Werten");
        setValue(L.DESC_COMMAND_LOREBOOK_PARAM, "Das Lorebook: sein Handle oder seine Nummer aus list-lorebooks; das Wurzel-Lorebook (1), wenn weggelassen");
        setValue(L.DESC_COMMAND_LORE_ENTRY_PARAM, "Der Eintrag: sein Handle oder seine Nummer in seinem Lorebook, der erste Eintrag ist 1");
        setValue(L.DESC_COMMAND_LORE_FILTER_PARAM, "Nur die Einträge, deren Name oder Tag diesen Text enthält (Groß-/Kleinschreibung egal)");
        setValue(L.DESC_COMMAND_LORE_QUERY_PARAM, "Der Text, der im Namen, Text und Kommentar der Einträge gesucht wird (Groß-/Kleinschreibung egal)");
        setValue(L.DESC_COMMAND_LIST_LOREBOOKS, "Listet die Lorebooks des geöffneten Buchs mit ihren Einträgen und Unterbüchern auf.");
        setValue(L.DESC_COMMAND_LIST_LOREBOOKS_LLM, "Listet die Lorebooks des Buchs auf: das Wurzel-Lorebook und den Baum seiner Unterbücher, jedes mit seiner Nummer (die Wurzel ist 1), Name, ob es aktiviert ist, wie viele Einträge es hat (und wie viele aktiviert sind), seinen Tags und den Nummern seiner Unterbücher. Andere Lorebooks des Benutzers sind nicht erreichbar. Lorebooks und Einträge werden über ihr Handle (bevorzuge es) oder über eine Nummer angegeben: ein Lorebook über diese Nummer, ein Eintrag über seine Nummer im Lorebook. Nur lesend. Jede Zeile hat außerdem ihr „handle“: Es ändert sich nicht, wenn etwas hinzugefügt oder gelöscht wird, und die Befehle, die das Buch ändern, nehmen es entgegen.");
        setValue(L.DESC_COMMAND_LIST_LOREBOOKS_RETURN, "JSON mit den Lorebooks: number, name, enabled, entries, enabledEntries, tags, subbooks");
        setValue(L.DESC_COMMAND_LIST_LORE_ENTRIES, "Listet die Einträge eines Lorebooks mit ihren Einstellungen und einer Vorschau auf.");
        setValue(L.DESC_COMMAND_LIST_LORE_ENTRIES_LLM, "Listet die Einträge eines Lorebooks auf (das Wurzel-Lorebook, sofern keine Lorebook-Nummer aus list-lorebooks angegeben ist): die Nummer des Eintrags im Lorebook, Name, ob er aktiviert ist, seine Reihenfolge, Einfügemodus, Filtermodus (KEYWORDS_OR- / KEYWORDS_AND-Schlüssel, TEXT oder ein REGEX), Tags, die Länge seines Textes und eine kurze Vorschau. Ein Filter behält die Einträge, deren Name oder Tag ihn enthält; die Nummern bleiben die des gesamten Lorebooks. Seitenweise: offset und limit. Einträge werden über ihre Nummer im Lorebook angesprochen (der erste ist 1). Nur lesend. Optionen sind positionsbezogen und optional, in der aufgeführten Reihenfolge. Jede Zeile hat außerdem ihr „handle“: Es ändert sich nicht, wenn etwas hinzugefügt oder gelöscht wird, und die Befehle, die das Buch ändern, nehmen es entgegen.");
        setValue(L.DESC_COMMAND_LIST_LORE_ENTRIES_RETURN, "JSON mit den Einträgen der Seite: entry, name, enabled, order, insertion, filtering, tags, payloadLength, preview");
        setValue(L.DESC_COMMAND_GET_LORE_ENTRY, "Zeigt einen Lorebook-Eintrag mit seinen Einstellungen und seinem Text.");
        setValue(L.DESC_COMMAND_GET_LORE_ENTRY_LLM, "Liest einen Eintrag eines Lorebooks (das Wurzel-Lorebook, sofern keine Lorebook-Nummer aus list-lorebooks angegeben ist): Name, ob er aktiviert ist, Reihenfolge, Einfügemodus, Filtermodus und seine Schlüssel (der Text oder der reguläre Ausdruck, der ihn aktiviert), Tags und negative Tags, den Kommentar und einen Ausschnitt des Textes mit Offset und Gesamtlänge (offset und length blättern durch einen langen Text). Der Eintrag wird über sein Handle oder über seine Nummer im Lorebook angegeben (der erste ist 1, siehe list-lore-entries). Nur lesend. Optionen sind positionsbezogen und optional, in der aufgeführten Reihenfolge. Jede Zeile hat außerdem ihr „handle“: Es ändert sich nicht, wenn etwas hinzugefügt oder gelöscht wird, und die Befehle, die das Buch ändern, nehmen es entgegen.");
        setValue(L.DESC_COMMAND_GET_LORE_ENTRY_RETURN, "JSON mit dem Eintrag: name, enabled, order, insertion, filtering, keys, tags, negativeTags, comment und ein Ausschnitt des payload");
        setValue(L.DESC_COMMAND_SEARCH_LORE, "Durchsucht die Namen, Texte und Kommentare der Lorebook-Einträge.");
        setValue(L.DESC_COMMAND_SEARCH_LORE_LLM, "Findet die Einträge aller Lorebooks des Buchs, deren Name, Text oder Kommentar die Anfrage enthält (Groß-/Kleinschreibung egal; mit regex ist die Anfrage ein regulärer Ausdruck). Jeder Treffer nennt die Lorebook-Nummer, die Eintragsnummer, den Namen, welche von Name, Text und Kommentar passen, und einen Ausschnitt um den ersten Treffer; found ist die Anzahl der passenden Einträge, hits ist begrenzt. Nur lesend. Optionen sind positionsbezogen und optional, in der aufgeführten Reihenfolge. Jede Zeile hat außerdem ihr „handle“: Es ändert sich nicht, wenn etwas hinzugefügt oder gelöscht wird, und die Befehle, die das Buch ändern, nehmen es entgegen.");
        setValue(L.DESC_COMMAND_SEARCH_LORE_RETURN, "JSON mit found und den Treffern: lorebook, entry, name, matchedIn, snippet");
        setValue(L.DESC_COMMAND_PREVIEW_TEXT_PARAM, "Der Text, in dem die Filter der Einträge gesucht werden, so wie der Benutzerprompt eines Zugs");
        setValue(L.DESC_COMMAND_PREVIEW_LORE_ACTIVATION, "Zeigt, welche Lorebook-Einträge eine Generierung für einen Text oder für einen Abschnitt verwenden würde und warum.");
        setValue(L.DESC_COMMAND_PREVIEW_LORE_ACTIVATION_LLM, "Sagt, welche Einträge der Lorebooks des Buchs die Generierung für einen Text oder für einen Zug wie den, der einen Abschnitt erzeugt hat (nach Position und optional Zweignummer angegeben), in den Prompt aufnehmen würde: Der Filter eines Eintrags wird im Text gesucht oder, bei einem Abschnitt, im Benutzerprompt des Buchs, gerendert aus den mit dem Abschnitt gespeicherten Anweisungen, der Szene, der Erzählperspektive und den anwesenden Figuren. Jeder verwendete Eintrag hat seine Lorebook-Nummer, Eintragsnummer, seinen Namen und den Grund (CONSTANT: kein Filter; FILTER_MATCHED); die nicht verwendeten haben ebenfalls den Grund (DISABLED, NEGATIVE_TAG oder MISSING_TAG gegenüber den Tags des Buchs, FILTER_NOT_MATCHED). Außerdem der Lore-Text, der eingefügt würde, mit seinen Tokens, aufgeteilt in den Lore-Block und die Lore, die vor dem Benutzerprompt steht. Der Rest der Geschichte steht den Vorlagen der Einträge hier nicht zur Verfügung. Nur lesend. Optionen sind positionsbezogen und optional, in der aufgeführten Reihenfolge. Jede Zeile hat außerdem ihr „handle“: Es ändert sich nicht, wenn etwas hinzugefügt oder gelöscht wird, und die Befehle, die das Buch ändern, nehmen es entgegen.");
        setValue(L.DESC_COMMAND_PREVIEW_LORE_ACTIVATION_RETURN, "JSON mit den verwendeten und nicht verwendeten Einträgen (mit den Gründen) und dem Lore-Text mit seinen Tokens");
        setValue(L.DESC_COMMAND_OLD_PARAM, "Der zu ersetzende Text, genau so, wie er im Abschnitt steht; er muss genau einmal gefunden werden");
        setValue(L.DESC_COMMAND_NEW_PARAM, "Der Text, der an seine Stelle tritt, darf leer sein, um den alten zu löschen");
        setValue(L.DESC_COMMAND_WRITE_FIELD_PARAM, "Das zu ändernde Feld: response (der Text des Abschnitts, Standard), instructions, scene, pov oder present");
        setValue(L.DESC_COMMAND_NEW_TEXT_PARAM, "Der Text");
        setValue(L.DESC_COMMAND_SEPARATOR_PARAM, "Was zwischen dem alten Ende und dem neuen Text steht; eine Leerzeile, wenn weggelassen (nichts, wenn der Abschnitt leer ist)");
        setValue(L.DESC_COMMAND_TURN_INSTRUCTIONS_PARAM, "Die Anweisungen des Zugs, aus dem der Abschnitt entstanden ist; leer löscht sie, weggelassen lässt sie, wie sie sind");
        setValue(L.DESC_COMMAND_TURN_SCENE_PARAM, "Der Schauplatz der Szene des Zugs; leer löscht ihn, weggelassen lässt ihn, wie er ist");
        setValue(L.DESC_COMMAND_TURN_POV_PARAM, "Die Perspektivfigur des Zugs; leer löscht sie, weggelassen lässt sie, wie sie ist");
        setValue(L.DESC_COMMAND_TURN_PRESENT_PARAM, "Die im Zug anwesenden Figuren; leer löscht sie, weggelassen lässt sie, wie sie sind");
        setValue(L.DESC_COMMAND_EDIT_PART, "Ersetzt ein Stück des Textes eines Abschnitts durch einen anderen Text. Parameter: part (Handle), old, new, field.");
        setValue(L.DESC_COMMAND_EDIT_PART_LLM, "Ändert einen Abschnitt der Geschichte: Das Textstück `old` wird durch `new` ersetzt. `old` muss im Abschnitt genau einmal passen (dieselben Leerzeichen und Zeilenumbrüche), sonst wird nichts geändert, und der Fehler nennt, wie oft es gefunden wurde: Nimm mehr Text drumherum dazu. Der Abschnitt wird über sein Handle angegeben. Zählt seine Wörter und Tokens und nennt, welche Zusammenfassungen veraltet sind (führe dann revalidate-summaries aus, wenn sie noch stimmen, oder generiere sie neu). Mit `field` werden stattdessen die Anweisungen, die Szene, pov oder die anwesenden Figuren des Zugs bearbeitet. Ändert das Buch.");
        setValue(L.DESC_COMMAND_EDIT_PART_RETURN, "JSON mit dem Abschnitt (handle, position, words, tokens) und den Zusammenfassungen, die veraltet sind");
        setValue(L.DESC_COMMAND_REPLACE_PART_TEXT, "Ersetzt den gesamten Text eines Abschnitts. Parameter: part (Handle), text, field.");
        setValue(L.DESC_COMMAND_REPLACE_PART_TEXT_LLM, "Ersetzt den gesamten Text eines Abschnitts der Geschichte durch `text` (oder mit `field` die gesamten Anweisungen, die Szene, pov oder die anwesenden Figuren des Zugs). Der alte Text geht verloren, verwende also für eine kleine Änderung edit-part und zum Anhängen am Ende append-to-part. Der Abschnitt wird über sein Handle angegeben. Zählt seine Wörter und Tokens und nennt, welche Zusammenfassungen veraltet sind. Ändert das Buch; der Benutzer wird um Bestätigung gebeten, ein Agent wird durch seinen destruktiven Modus abgedeckt.");
        setValue(L.DESC_COMMAND_REPLACE_PART_TEXT_RETURN, "JSON mit dem Abschnitt (handle, position, words, tokens) und den Zusammenfassungen, die veraltet sind");
        setValue(L.DESC_COMMAND_APPEND_TO_PART, "Fügt Text am Ende eines Abschnitts hinzu. Parameter: part (Handle), text, separator.");
        setValue(L.DESC_COMMAND_APPEND_TO_PART_LLM, "Fügt `text` am Ende des Textes eines Abschnitts der Geschichte hinzu, nach `separator` (eine Leerzeile, wenn weggelassen, nichts, wenn der Abschnitt leer ist). Verwende es, um einen Abschnitt fortzusetzen; um einen neuen Abschnitt zu schreiben, verwende create-part. Der Abschnitt wird über sein Handle angegeben. Zählt seine Wörter und Tokens und nennt, welche Zusammenfassungen veraltet sind. Ändert das Buch.");
        setValue(L.DESC_COMMAND_APPEND_TO_PART_RETURN, "JSON mit dem Abschnitt (handle, position, words, tokens) und den Zusammenfassungen, die veraltet sind");
        setValue(L.DESC_COMMAND_SET_PART_FIELDS, "Ändert, woraus ein Abschnitt entstanden ist: Anweisungen, Szene, pov und anwesende Figuren. Parameter: part (Handle), instructions, scene, pov, present.");
        setValue(L.DESC_COMMAND_SET_PART_FIELDS_LLM, "Ändert die mit einem Abschnitt der Geschichte gespeicherte Zugeingabe: die Anweisungen, den Schauplatz der Szene, die Perspektivfigur und die anwesenden Figuren, aus denen eine neue Generierung des Abschnitts (Variante, Neugenerierung) erneut erfolgt. Nur die angegebenen Felder werden geändert, ein leerer Text leert ein Feld. Ändert nicht den Text des Abschnitts. Der Abschnitt wird über sein Handle angegeben. Ändert das Buch.");
        setValue(L.DESC_COMMAND_SET_PART_FIELDS_RETURN, "JSON mit dem Abschnitt und der Zugeingabe, die er jetzt hat");
        setValue(L.DESC_COMMAND_PART_HANDLE_PARAM, "Das Handle des Abschnitts (das „handle“ der Listen, z. B. von list-parts); eine Position wird nicht akzeptiert");
        setValue(L.DESC_COMMAND_PARENT_PARAM, "Der Abschnitt, nach dem der neue Abschnitt kommt (sein Handle); der letzte Abschnitt des aktiven Zweigs, wenn weggelassen, der erste Abschnitt der Geschichte, wenn das Buch leer ist");
        setValue(L.DESC_COMMAND_SUMMARY_TEXT_PARAM, "Der neue Text der Zusammenfassung");
        setValue(L.DESC_COMMAND_UNWIND_PARAM, "Bei einer Metazusammenfassung die ersetzte Zusammenfassung zurückbringen, statt den Abschnitt ohne eine zu lassen; false, wenn weggelassen");
        setValue(L.DESC_COMMAND_REVALIDATE_PART_PARAM, "Der Abschnitt, dessen Zusammenfassung neu validiert wird (sein Handle); alle Zusammenfassungen des aktiven Zweigs, wenn weggelassen");
        setValue(L.DESC_COMMAND_BOOK_NAME_PARAM, "Der neue Name des Buchs");
        setValue(L.DESC_COMMAND_BOOK_DESCRIPTION_PARAM, "Die neue Beschreibung des Buchs");
        setValue(L.DESC_COMMAND_BOOK_POV_PARAM, "Die Erzählperspektive des Buchs, ein freier Text wie „Dritte Person, begrenzt“");
        setValue(L.DESC_COMMAND_BOOK_TENSE_PARAM, "Die Erzählzeit des Buchs, ein freier Text wie „Präteritum“");
        setValue(L.DESC_COMMAND_BOOK_STYLE_PARAM, "Der Stil, in dem das Buch geschrieben ist, ein freier Text");
        setValue(L.DESC_COMMAND_BOOK_LANGUAGE_PARAM, "Die Sprache des Buchs: ihr Name (Englisch) oder ISO-639-1-Code (en)");
        setValue(L.DESC_COMMAND_BOOK_TEMPLATE_PARAM, "Die Hauptvorlage des Buchs, der Systemprompt jeder Generierung (eine Handlebars-Vorlage)");
        setValue(L.DESC_COMMAND_BOOK_USER_PROMPT_PARAM, "Die Vorlage des Benutzerprompts eines Zugs");
        setValue(L.DESC_COMMAND_BOOK_SUMMARY_PROMPT_PARAM, "Die Vorlage des Prompts, der eine Zusammenfassung erstellt");
        setValue(L.DESC_COMMAND_BOOK_META_SUMMARY_PROMPT_PARAM, "Die Vorlage des Prompts, der eine Metazusammenfassung erstellt");
        setValue(L.DESC_COMMAND_TAGS_ADD_PARAM, "Tags, die dem Buch hinzugefügt werden, durch Kommas getrennt");
        setValue(L.DESC_COMMAND_TAGS_REMOVE_PARAM, "Tags, die vom Buch entfernt werden, durch Kommas getrennt");
        setValue(L.DESC_COMMAND_CREATE_PART, "Schreibt einen neuen Abschnitt der Geschichte. Parameter: text, parent (Handle), instructions, scene, pov, present.");
        setValue(L.DESC_COMMAND_CREATE_PART_LLM, "Fügt der Geschichte einen neuen Abschnitt mit dem angegebenen Text hinzu: nach dem Abschnitt `parent` (sein Handle) oder nach dem letzten Abschnitt des aktiven Zweigs, wenn `parent` weggelassen wird (der erste Abschnitt eines leeren Buchs). Ein Abschnitt, der einen Abschnitt fortsetzt, der bereits eine Fortsetzung hat, beginnt einen neuen Zweig. Der neue Abschnitt wird zum Ende des aktiven Zweigs. Speichert optional die Zugeingabe (instructions, scene, pov, present), für die er steht. Verwende es, um Text selbst zu schreiben; damit das Modell ihn schreibt, verwende next. Ändert das Buch. Gibt das Handle des neuen Abschnitts zurück.");
        setValue(L.DESC_COMMAND_CREATE_PART_RETURN, "JSON mit dem neuen Abschnitt (handle, position, words, tokens) und der Länge des Zweigs");
        setValue(L.DESC_COMMAND_BRANCH_PART, "Legt eine Kopie eines Abschnitts neben ihm als neuen Zweig an. Parameter: part (Handle).");
        setValue(L.DESC_COMMAND_BRANCH_PART_LLM, "Kopiert den Abschnitt (und seine Zusammenfassung) als sein Geschwister, eine neue Variante, die einen neuen Zweig beginnt, und macht die Kopie zum Ende des aktiven Zweigs. Die Abschnitte, die auf das Original folgen, bleiben beim Original. Verwende es, um eine andere Version eines Abschnitts auszuprobieren, ohne die erste zu verlieren. Der Abschnitt wird über sein Handle angegeben. Ändert das Buch. Gibt das Handle der Kopie zurück.");
        setValue(L.DESC_COMMAND_BRANCH_PART_RETURN, "JSON mit dem neuen Abschnitt (handle, position, words, tokens) und dem Handle, von dem kopiert wurde");
        setValue(L.DESC_COMMAND_DELETE_PART, "Löscht einen Abschnitt der Geschichte; die darauf folgenden Abschnitte bleiben. Parameter: part (Handle).");
        setValue(L.DESC_COMMAND_DELETE_PART_LLM, "Löscht einen Abschnitt der Geschichte und seine Zusammenfassung. Die Abschnitte, die darauf folgten, bleiben und setzen seinen übergeordneten Abschnitt fort, sodass alles danach eine Position nach oben rückt. Zusammenfassungen der Abschnitte danach können veralten (die Antwort listet sie auf). Der Abschnitt wird über sein Handle angegeben. Ändert das Buch; der Benutzer wird um Bestätigung gebeten, ein Agent wird durch seinen destruktiven Modus abgedeckt.");
        setValue(L.DESC_COMMAND_DELETE_PART_RETURN, "JSON mit dem Handle des gelöschten Abschnitts, wie viele Abschnitte darauf folgten, dem jetzt aktiven Abschnitt und den Zusammenfassungen, die veraltet sind");
        setValue(L.DESC_COMMAND_SWITCH_BRANCH, "Macht den Zweig durch einen Abschnitt zum aktiven. Parameter: part (Handle).");
        setValue(L.DESC_COMMAND_SWITCH_BRANCH_LLM, "Macht den Zweig, der durch den Abschnitt führt, zum aktiven Zweig des Buchs: Sein Ende ist die neueste Fortsetzung unterhalb des Abschnitts. Das bewirkt auch die Wahl einer anderen Variante. Der Abschnitt wird über sein Handle angegeben (siehe list-swipes und list-branches). Ändert, auf welchen Abschnitten die Befehle ohne Zweig arbeiten und was die nächste Generierung fortsetzt. Ändert das Buch.");
        setValue(L.DESC_COMMAND_SWITCH_BRANCH_RETURN, "JSON mit dem Abschnitt, dem Handle des Endes des Zweigs und seiner Länge");
        setValue(L.DESC_COMMAND_SET_SUMMARY, "Ersetzt den Text der Zusammenfassung eines Abschnitts. Parameter: part (Handle), text.");
        setValue(L.DESC_COMMAND_SET_SUMMARY_LLM, "Ersetzt den Text der Zusammenfassung, die an einem Abschnitt der Geschichte sitzt (der Abschnitt muss eine haben). Die Zusammenfassung steht für die Abschnitte bis zu ihrem Abschnitt; ihre Tokens werden neu gezählt. Eine darüberliegende Metazusammenfassung, die sie einschließt, kann veralten (die Antwort listet sie auf). Der Abschnitt wird über sein Handle angegeben. Ändert das Buch.");
        setValue(L.DESC_COMMAND_SET_SUMMARY_RETURN, "JSON mit dem Abschnitt, den Tokens der Zusammenfassung und den Zusammenfassungen, die veraltet sind");
        setValue(L.DESC_COMMAND_REMOVE_SUMMARY, "Entfernt die Zusammenfassung eines Abschnitts. Parameter: part (Handle), unwind.");
        setValue(L.DESC_COMMAND_REMOVE_SUMMARY_LLM, "Entfernt die Zusammenfassung, die an einem Abschnitt der Geschichte sitzt, sodass die Generierung statt ihrer wieder die Abschnitte selbst verwendet. Mit `unwind` wird eine Metazusammenfassung durch die Zusammenfassung ersetzt, die sie ersetzt hatte. Der Abschnitt wird über sein Handle angegeben. Ändert das Buch; der Benutzer wird um Bestätigung gebeten, ein Agent wird durch seinen destruktiven Modus abgedeckt.");
        setValue(L.DESC_COMMAND_REMOVE_SUMMARY_RETURN, "JSON mit dem Abschnitt und ob er jetzt eine Zusammenfassung hat");
        setValue(L.DESC_COMMAND_REVALIDATE_SUMMARIES, "Erklärt, dass die veralteten Zusammenfassungen die Geschichte noch beschreiben. Parameter: part (Handle).");
        setValue(L.DESC_COMMAND_REVALIDATE_SUMMARIES_LLM, "Markiert die Zusammenfassungen, die durch eine Bearbeitung veraltet sind, wieder als gültig: Der Hash der Geschichte, die sie beschreiben, wird neu berechnet. Verwende es nur, wenn du geprüft hast, dass das, was die Zusammenfassung sagt, nach der Bearbeitung noch stimmt (ein Tippfehler korrigiert, ein Name geändert); eine Zusammenfassung, die Ereignisse beschreibt, die sich geändert haben, muss mit regenerate-summary neu erstellt werden. Ohne `part` alle Zusammenfassungen des aktiven Zweigs, mit `part` nur die Zusammenfassung dieses Abschnitts (sein Handle). Ändert das Buch.");
        setValue(L.DESC_COMMAND_REVALIDATE_SUMMARIES_RETURN, "JSON damit, wie viele Zusammenfassungen neu validiert wurden, und ihren Abschnitten");
        setValue(L.DESC_COMMAND_SET_BOOK_INFO, "Ändert den Namen, die Beschreibung, die Erzählperspektive, die Zeitform, den Stil oder die Sprache des Buchs. Parameter: name, description, pov, tense, style, language.");
        setValue(L.DESC_COMMAND_SET_BOOK_INFO_LLM, "Ändert die beschreibenden Einstellungen des Buchs: seinen Namen, seine Beschreibung, Erzählperspektive, Zeitform, seinen Stil und seine Sprache. Nur die angegebenen Werte werden geändert, der Rest bleibt (ein leerer Text leert ein Feld, der Name darf nicht leer sein). Die Sprache, die Erzählperspektive, die Zeitform und der Stil werden in den Prompts der Generierung verwendet. Das Modell, das Lorebook und die Prompt-Vorlagen werden hier nicht geändert. Ändert das Buch.");
        setValue(L.DESC_COMMAND_SET_BOOK_INFO_RETURN, "JSON mit den Einstellungen des Buchs nach der Änderung");
        setValue(L.DESC_COMMAND_SET_BOOK_PROMPTS, "Ersetzt die Prompt-Vorlagen des Buchs. Parameter: template, userPrompt, summaryPrompt, metaSummaryPrompt.");
        setValue(L.DESC_COMMAND_SET_BOOK_PROMPTS_LLM, "Ersetzt die Prompt-Vorlagen, mit denen die Generierung des Buchs erfolgt: die Hauptvorlage (der Systemprompt), den Benutzerprompt eines Zugs und die Prompts der Zusammenfassung und der Metazusammenfassung. Nur die angegebenen Vorlagen werden geändert. Jede wird zuerst geprüft: Eine ungültige Vorlage wird abgelehnt und nichts wird geändert, eine, die nicht existierende Namen verwendet, wird gespeichert, und die Antwort nennt welche. Jede spätere Generierung des Buchs verwendet die Vorlagen, eine schlechte verdirbt also die Geschichte: Ändere sie nur, wenn du darum gebeten wirst. Ändert das Buch; der Benutzer wird um Bestätigung gebeten, ein Agent wird durch seinen destruktiven Modus abgedeckt.");
        setValue(L.DESC_COMMAND_SET_BOOK_PROMPTS_RETURN, "JSON mit den geänderten Vorlagen und den Warnungen zu nicht existierenden Namen");
        setValue(L.DESC_COMMAND_SET_BOOK_TAGS, "Fügt dem Buch Tags hinzu oder entfernt sie. Parameter: add, remove (durch Kommas getrennt).");
        setValue(L.DESC_COMMAND_SET_BOOK_TAGS_LLM, "Fügt dem Buch Tags hinzu und entfernt Tags davon; beides sind durch Kommas getrennte Listen, jede kann weggelassen werden. Die Tags des Buchs bestimmen, welche auf Tags beschränkten Lorebook-Einträge verwendet werden. Ein Tag, der nicht existiert, wird angelegt. Ändert das Buch.");
        setValue(L.DESC_COMMAND_SET_BOOK_TAGS_RETURN, "JSON mit den Tags des Buchs nach der Änderung");
        setValue(L.DESC_COMMAND_LORE_ENTRY_HANDLE_PARAM, "Das Handle des Eintrags (das „handle“ von list-lore-entries); eine Nummer wird nicht akzeptiert");
        setValue(L.DESC_COMMAND_LOREBOOK_HANDLE_PARAM, "Das Handle des Lorebooks (das „handle“ von list-lorebooks); eine Nummer wird nicht akzeptiert");
        setValue(L.DESC_COMMAND_TARGET_LOREBOOK_PARAM, "Das Handle des Lorebooks, in dem der Eintrag ist; das Wurzel-Lorebook, wenn weggelassen");
        setValue(L.DESC_COMMAND_LORE_NAME_PARAM, "Der Name des Eintrags");
        setValue(L.DESC_COMMAND_LORE_PAYLOAD_PARAM, "Der Text des Eintrags, eine Handlebars-Vorlage; er geht in den Prompt, wenn der Eintrag verwendet wird");
        setValue(L.DESC_COMMAND_LORE_COMMENT_PARAM, "Eine Notiz zum Eintrag für den Autor, sie kommt nicht in den Prompt");
        setValue(L.DESC_COMMAND_LORE_ENABLED_PARAM, "Ob der Eintrag verwendet wird, true wenn weggelassen");
        setValue(L.DESC_COMMAND_LORE_ORDER_PARAM, "Wo der Eintrag unter den verwendeten Einträgen aller Lorebooks steht: niedriger kommt zuerst, bei gleicher Reihenfolge nach Erstellungszeit; 100, wenn weggelassen. get-lore-entry und list-lore-entries zeigen die Reihenfolge der anderen");
        setValue(L.DESC_COMMAND_LORE_KEYS_PARAM, "Die Wörter (eine durch Kommas getrennte Liste wie \"Name, Nachname\") oder der reguläre Ausdruck im Text des Zugs, die den Eintrag verwenden lassen; leer für einen Eintrag, der immer verwendet wird");
        setValue(L.DESC_COMMAND_LORE_FILTERING_MODE_PARAM, "Wie die Schlüssel abgeglichen werden: KEYWORDS_OR (die Schlüssel sind eine durch Kommas getrennte Liste, einer davon im Text lässt den Eintrag verwenden), KEYWORDS_AND (alle müssen im Text sein), TEXT (die Schlüssel sind ein Text) oder REGEX; KEYWORDS_OR, wenn beim Erstellen weggelassen, unverändert beim Aktualisieren");
        setValue(L.DESC_COMMAND_LORE_INSERTION_MODE_PARAM, "Wohin der Text kommt: IN_LORE_BLOCK (in den Lore-Block, in der Reihenfolge der Einträge) oder BEFORE_USER_PROMPT (direkt vor die Anfrage, wo das Modell am meisten Aufmerksamkeit schenkt; für das, was genau diesen Abschnitt beeinflussen muss, sparsam verwenden); IN_LORE_BLOCK, wenn weggelassen");
        setValue(L.DESC_COMMAND_LORE_TAGS_PARAM, "Tags des Eintrags, durch Kommas getrennt: Der Eintrag wird nur in Büchern verwendet, die einen davon haben");
        setValue(L.DESC_COMMAND_LORE_TAGS_ADD_PARAM, "Tags, die dem Eintrag hinzugefügt werden, durch Kommas getrennt");
        setValue(L.DESC_COMMAND_LORE_TAGS_REMOVE_PARAM, "Tags, die vom Eintrag entfernt werden, durch Kommas getrennt");
        setValue(L.DESC_COMMAND_LORE_NEGATIVE_ADD_PARAM, "Negative Tags zum Hinzufügen, durch Kommas getrennt: Der Eintrag wird nicht in Büchern verwendet, die einen davon haben");
        setValue(L.DESC_COMMAND_LORE_NEGATIVE_REMOVE_PARAM, "Negative Tags, die vom Eintrag entfernt werden, durch Kommas getrennt");
        setValue(L.DESC_COMMAND_LOREBOOK_NAME_PARAM, "Der Name des Lorebooks");
        setValue(L.DESC_COMMAND_LOREBOOK_ENABLED_PARAM, "Ob das Lorebook verwendet wird");
        setValue(L.DESC_COMMAND_PARENT_LOREBOOK_PARAM, "Das Handle des Lorebooks, das das neue als Unterbuch erhält; das Wurzel-Lorebook, wenn weggelassen");
        setValue(L.DESC_COMMAND_SUBBOOK_PARAM, "Das Handle des Lorebooks, das ein Unterbuch ist (oder aufhört, eines zu sein)");
        setValue(L.DESC_COMMAND_CREATE_LORE_ENTRY, "Fügt einem Lorebook einen Eintrag hinzu. Parameter: name, payload, lorebook (Handle), comment, enabled, order, keys, filteringMode, insertionMode, tags.");
        setValue(L.DESC_COMMAND_CREATE_LORE_ENTRY_LLM, "Fügt einem Lorebook des Buchs einen neuen Eintrag hinzu (das Wurzel-Lorebook, wenn `lorebook` weggelassen wird). `payload` ist der Text, der in den Prompt geht, eine Handlebars-Vorlage. Ein Eintrag ohne `keys` wird immer verwendet, sonst wird er verwendet, wenn die Schlüssel im Text des Zugs stehen: `keys` ist eine durch Kommas getrennte Liste von Wörtern (zum Beispiel \"Anna, Novak\"), der Eintrag wird verwendet, wenn eines davon vorkommt (filteringMode KEYWORDS_OR, der Standard) oder wenn alle vorkommen (KEYWORDS_AND); filteringMode TEXT nimmt das gesamte `keys` als einen Text und REGEX als regulären Ausdruck. Ein Problem der Vorlage oder des regulären Ausdrucks verhindert das Speichern nicht, es wird in der Antwort gemeldet: Behebe es mit update-lore-entry. `order` (niedriger kommt zuerst, 100, wenn weggelassen) setzt den Eintrag unter den verwendeten Einträgen früher oder später: Lies die `order` der anderen mit list-lore-entries, um ihn dazwischen zu platzieren. `insertionMode` BEFORE_USER_PROMPT verschiebt den Text aus dem Lore-Block direkt vor die Anfrage. Ändert das Buch. Gibt das Handle des Eintrags zurück.");
        setValue(L.DESC_COMMAND_CREATE_LORE_ENTRY_RETURN, "JSON mit dem Eintrag (handle, name) und den Problemen seines Textes oder Filters, falls vorhanden");
        setValue(L.DESC_COMMAND_UPDATE_LORE_ENTRY, "Ändert die Felder eines Lorebook-Eintrags. Parameter: entry (Handle), name, payload, comment, enabled, order, keys, filteringMode, insertionMode.");
        setValue(L.DESC_COMMAND_UPDATE_LORE_ENTRY_LLM, "Ändert den Eintrag mit dem angegebenen Handle: Nur die angegebenen Felder werden geändert. Um ein Stück eines langen Textes zu ändern, lies ihn mit get-lore-entry und gib das gesamte neue `payload` an. Ein Problem der Vorlage oder des regulären Ausdrucks verhindert das Speichern nicht, es wird in der Antwort gemeldet. `order` und `insertionMode` verschieben den Eintrag im Prompt (siehe create-lore-entry). Um die Tags zu ändern, verwende set-lore-entry-tags, zum Verschieben move-lore-entry. Ändert das Buch.");
        setValue(L.DESC_COMMAND_UPDATE_LORE_ENTRY_RETURN, "JSON mit dem Eintrag (handle, name) und den Problemen seines Textes oder Filters, falls vorhanden");
        setValue(L.DESC_COMMAND_DELETE_LORE_ENTRY, "Löscht einen Eintrag eines Lorebooks. Parameter: entry (Handle).");
        setValue(L.DESC_COMMAND_DELETE_LORE_ENTRY_LLM, "Löscht den Eintrag mit dem angegebenen Handle aus seinem Lorebook. Die Nummern der Einträge danach im Lorebook ändern sich, die Handles nicht. Ändert das Buch; der Benutzer wird um Bestätigung gebeten, ein Agent wird durch seinen destruktiven Modus abgedeckt.");
        setValue(L.DESC_COMMAND_DELETE_LORE_ENTRY_RETURN, "JSON mit dem Handle und dem Namen des gelöschten Eintrags");
        setValue(L.DESC_COMMAND_MOVE_LORE_ENTRY, "Verschiebt einen Eintrag in ein anderes Lorebook des Buchs. Parameter: entry (Handle), lorebook (Handle).");
        setValue(L.DESC_COMMAND_MOVE_LORE_ENTRY_LLM, "Verschiebt den Eintrag in ein anderes Lorebook des Buchs (das Wurzel-Lorebook oder eines seiner Unterbücher). Seine Felder und Tags bleiben. Ändert das Buch.");
        setValue(L.DESC_COMMAND_MOVE_LORE_ENTRY_RETURN, "JSON mit dem Eintrag (handle, name) und den Problemen seines Textes oder Filters, falls vorhanden");
        setValue(L.DESC_COMMAND_SET_LORE_ENTRY_TAGS, "Fügt die Tags und die negativen Tags eines Eintrags hinzu und entfernt sie. Parameter: entry (Handle), add, remove, addNegative, removeNegative (durch Kommas getrennt).");
        setValue(L.DESC_COMMAND_SET_LORE_ENTRY_TAGS_LLM, "Ändert die Tags des Eintrags mit dem angegebenen Handle; jede der Listen ist durch Kommas getrennt und kann weggelassen werden. Ein Eintrag mit Tags wird nur in Büchern verwendet, die einen davon haben, ein Eintrag mit negativen Tags wird nicht in Büchern verwendet, die einen davon haben (siehe die Tags des Buchs, set-book-tags). Ein Tag, der nicht existiert, wird angelegt. Ändert das Buch.");
        setValue(L.DESC_COMMAND_SET_LORE_ENTRY_TAGS_RETURN, "JSON mit den Tags und den negativen Tags des Eintrags nach der Änderung");
        setValue(L.DESC_COMMAND_CREATE_LOREBOOK, "Erstellt ein neues Lorebook, das ein Unterbuch eines anderen ist. Parameter: name, parent (Handle).");
        setValue(L.DESC_COMMAND_CREATE_LOREBOOK_LLM, "Erstellt ein neues, leeres Lorebook und fügt es als Unterbuch des Lorebooks `parent` hinzu (das Wurzel-Lorebook, wenn weggelassen), sodass seine Einträge im Buch verwendet werden. Ändert das Buch. Gibt das Handle des neuen Lorebooks zurück.");
        setValue(L.DESC_COMMAND_CREATE_LOREBOOK_RETURN, "JSON mit dem neuen Lorebook (handle, number, name)");
        setValue(L.DESC_COMMAND_SET_LOREBOOK, "Benennt ein Lorebook um oder schaltet es ein oder aus. Parameter: lorebook (Handle), name, enabled.");
        setValue(L.DESC_COMMAND_SET_LOREBOOK_LLM, "Ändert den Namen eines Lorebooks des Buchs oder ob es verwendet wird: Die Einträge eines deaktivierten Lorebooks werden nicht verwendet. Nur die angegebenen Werte werden geändert. Ändert das Buch.");
        setValue(L.DESC_COMMAND_SET_LOREBOOK_RETURN, "JSON mit dem Lorebook (handle, number, name, enabled)");
        setValue(L.DESC_COMMAND_ADD_SUBBOOK, "Macht ein Lorebook des Buchs zum Unterbuch eines anderen. Parameter: lorebook (Handle), subbook (Handle).");
        setValue(L.DESC_COMMAND_ADD_SUBBOOK_LLM, "Macht das Lorebook `subbook` zum Unterbuch des Lorebooks `lorebook`, sodass seine Einträge überall verwendet werden, wo das Lorebook verwendet wird. Beide müssen Lorebooks dieses Buchs sein; ein Lorebook kann sich nicht selbst enthalten, weder direkt noch über seine Unterbücher (das wird abgelehnt). Ein Lorebook, das in diesem Lauf gelöscht oder aus seinem übergeordneten entfernt wurde, kann über sein Handle als `subbook` angegeben werden: Das Hinzufügen bringt es mit seinen Einträgen zurück. Ändert das Buch.");
        setValue(L.DESC_COMMAND_ADD_SUBBOOK_RETURN, "JSON mit dem Lorebook und seinen Unterbüchern");
        setValue(L.DESC_COMMAND_REMOVE_SUBBOOK, "Beendet, dass ein Lorebook ein Unterbuch eines anderen ist. Parameter: lorebook (Handle), subbook (Handle).");
        setValue(L.DESC_COMMAND_REMOVE_SUBBOOK_LLM, "Nimmt das Lorebook `subbook` aus den Unterbüchern des Lorebooks `lorebook`; nichts geschieht, wenn es keines ist. Das Lorebook wird nicht gelöscht, aber wenn kein anderes Lorebook es als Unterbuch hat, werden seine Einträge im Buch nicht mehr verwendet; du kannst es aber weiterhin über sein Handle ansprechen und mit add-subbook wieder hinzufügen. Ändert das Buch.");
        setValue(L.DESC_COMMAND_REMOVE_SUBBOOK_RETURN, "JSON mit dem Lorebook und seinen Unterbüchern");
        setValue(L.DESC_COMMAND_DELETE_LOREBOOK, "Löscht ein Lorebook mit seinen Einträgen. Parameter: lorebook (Handle).");
        setValue(L.DESC_COMMAND_DELETE_LOREBOOK_LLM, "Löscht ein Lorebook des Buchs mit allen seinen Einträgen und nimmt es aus den Unterbüchern der Lorebooks, die es hatten. Es wird nur als gelöscht markiert: add-subbook mit seinem Handle bringt es mit seinen Einträgen zurück. Das Wurzel-Lorebook des Buchs kann nicht gelöscht werden. Ändert das Buch; der Benutzer wird um Bestätigung gebeten, ein Agent wird durch seinen destruktiven Modus abgedeckt.");
        setValue(L.DESC_COMMAND_DELETE_LOREBOOK_RETURN, "JSON mit dem Handle und dem Namen des gelöschten Lorebooks und wie viele Einträge es hatte");
        setValue(L.DESC_COMMAND_MAX_HITS_PARAM, "Das Ersetzen ablehnen, wenn es mehr Treffer als diese gibt; kein Limit, wenn weggelassen");
        setValue(L.DESC_COMMAND_DRY_RUN_PARAM, "Nur die Treffer zählen und einige davon zeigen, nichts ändern; false, wenn weggelassen");
        setValue(L.DESC_COMMAND_GEN_INSTRUCTIONS_PARAM, "Was der neue Abschnitt tun oder enthalten soll; bei swipe und regenerate die Anweisungen, aus denen der Abschnitt entstanden ist, wenn weggelassen");
        setValue(L.DESC_COMMAND_GEN_SCENE_PARAM, "Der Schauplatz der Szene des Zugs; bei swipe und regenerate der, aus dem der Abschnitt entstanden ist, wenn weggelassen");
        setValue(L.DESC_COMMAND_GEN_POV_PARAM, "Die Perspektivfigur des Zugs; bei swipe und regenerate die, aus der der Abschnitt entstanden ist, wenn weggelassen");
        setValue(L.DESC_COMMAND_GEN_PRESENT_PARAM, "Die im Zug anwesenden Figuren; bei swipe und regenerate die, aus denen der Abschnitt entstanden ist, wenn weggelassen");
        setValue(L.DESC_COMMAND_AFTER_PART_PARAM, "Der Abschnitt, nach dem fortgesetzt wird (sein Handle), der zuerst zum Ende des aktiven Zweigs wird; das Ende des aktiven Zweigs, wenn weggelassen");
        setValue(L.DESC_COMMAND_GEN_PROFILE_PARAM, "Die Rolle eines der Modellprofile des Agenten, mit dem geschrieben wird; das Hauptprofil, wenn weggelassen");
        setValue(L.DESC_COMMAND_GEN_PART_PARAM, "Der neu zu schreibende Abschnitt (sein Handle); er muss der letzte Abschnitt seines Zweigs sein. Das Ende des aktiven Zweigs, wenn weggelassen");
        setValue(L.DESC_COMMAND_META_FROM_PARAM, "Der neueste Abschnitt des zusammenzuführenden Bereichs (sein Handle); die Metazusammenfassung sitzt an ihm");
        setValue(L.DESC_COMMAND_META_TO_PARAM, "Der älteste Abschnitt des zusammenzuführenden Bereichs (sein Handle)");
        setValue(L.DESC_COMMAND_NEXT, "Lässt das Modell den nächsten Abschnitt der Geschichte schreiben. Parameter: scene, pov, present, instructions, after (Handle), profile.");
        setValue(L.DESC_COMMAND_NEXT_LLM, "Lässt das Modell den nächsten Abschnitt der Geschichte nach dem Ende des aktiven Zweigs (oder nach dem Abschnitt `after`) schreiben, so wie es die Schaltfläche „Neuer Zug“ tut: Der Prompt wird aus dem Buch (Vorlage, Lore, Zusammenfassungen, die bisherige Geschichte) und der hier angegebenen Zugeingabe aufgebaut. Langsam und kostet Tokens des Modells des Buchs (oder des `profile` des Agenten); es läuft nur eine Generierung eines Buchs gleichzeitig, die anderen warten. Der neue Abschnitt wird zum Ende des aktiven Zweigs. Gibt das Handle des neuen Abschnitts zurück; lies ihn mit get-part. Ändert das Buch. Asynchron.");
        setValue(L.DESC_COMMAND_NEXT_RETURN, "JSON mit dem neuen Abschnitt (handle, position, words, tokens, model) und den Warnungen der Generierung");
        setValue(L.DESC_COMMAND_SWIPE, "Lässt das Modell eine andere Version des letzten Abschnitts neben der ersten schreiben. Parameter: part (Handle), scene, pov, present, instructions, profile.");
        setValue(L.DESC_COMMAND_SWIPE_LLM, "Lässt das Modell eine andere Version eines Abschnitts schreiben (eine Variante): ein neues Geschwister des Abschnitts, erzeugt aus demselben Zug (oder der hier angegebenen geänderten Zugeingabe), das zum Ende des aktiven Zweigs wird; die erste Version bleibt als anderer Zweig erhalten (siehe list-swipes, switch-branch). Der Abschnitt muss der letzte Abschnitt seines Zweigs sein. Langsam und kostet Tokens; es läuft nur eine Generierung eines Buchs gleichzeitig. Gibt das Handle des neuen Abschnitts zurück. Ändert das Buch. Asynchron.");
        setValue(L.DESC_COMMAND_SWIPE_RETURN, "JSON mit dem neuen Abschnitt (handle, position, words, tokens, model) und den Warnungen der Generierung");
        setValue(L.DESC_COMMAND_REGENERATE, "Lässt das Modell den letzten Abschnitt neu schreiben und ersetzt seinen Text. Parameter: part (Handle), scene, pov, present, instructions, profile.");
        setValue(L.DESC_COMMAND_REGENERATE_LLM, "Lässt das Modell den letzten Abschnitt eines Zweigs neu schreiben und ersetzt den Text des Abschnitts an Ort und Stelle (um den alten zu behalten, verwende swipe). Der Abschnitt muss der letzte Abschnitt seines Zweigs sein. Der alte Text geht verloren, außer wenn die Generierung fehlschlägt, dann bleibt er. Langsam und kostet Tokens; es läuft nur eine Generierung eines Buchs gleichzeitig. Gibt das Handle des Abschnitts zurück. Ändert das Buch; der Benutzer wird um Bestätigung gebeten, ein Agent wird durch seinen destruktiven Modus abgedeckt. Asynchron.");
        setValue(L.DESC_COMMAND_REGENERATE_RETURN, "JSON mit dem neuen Abschnitt (handle, position, words, tokens, model) und den Warnungen der Generierung");
        setValue(L.DESC_COMMAND_REGENERATE_SUMMARY, "Lässt das Modell die Zusammenfassung, die an einem Abschnitt endet, neu erstellen. Parameter: part (Handle).");
        setValue(L.DESC_COMMAND_REGENERATE_SUMMARY_LLM, "Lässt das Modell die Zusammenfassung, die an dem Abschnitt sitzt (der Kopf eines Zusammenfassungsblocks), aus den Abschnitten schreiben, für die sie steht, und setzt sie an die Stelle der alten an den Abschnitt, sodass eine veraltete Zusammenfassung wieder gültig wird. Langsam und kostet Tokens des Modells des Buchs. Der Abschnitt wird über sein Handle angegeben. Ändert das Buch. Asynchron.");
        setValue(L.DESC_COMMAND_REGENERATE_SUMMARY_RETURN, "JSON mit dem Abschnitt, den Tokens der neuen Zusammenfassung und dem Anfang ihres Textes");
        setValue(L.DESC_COMMAND_CREATE_META_SUMMARY, "Lässt das Modell die Zusammenfassungen eines Bereichs zu einer zusammenführen. Parameter: from (Handle), to (Handle).");
        setValue(L.DESC_COMMAND_CREATE_META_SUMMARY_LLM, "Lässt das Modell die Zusammenfassungen vom Abschnitt `from` (dem neuesten) bis zurück zum Abschnitt `to` (dem ältesten, aufgerundet auf das Ende seines Zusammenfassungsblocks) zu einer Metazusammenfassung zusammenführen, die an `from` sitzt und die Stelle der dort vorhandenen Zusammenfassung einnimmt. Verwende es, damit eine lange Geschichte in den Kontext passt. Beide Abschnitte liegen im selben Zweig und haben Zusammenfassungen. Langsam und kostet Tokens des Modells des Buchs. Ändert das Buch. Asynchron.");
        setValue(L.DESC_COMMAND_CREATE_META_SUMMARY_RETURN, "JSON mit dem Abschnitt, den Tokens der Metazusammenfassung und dem Anfang ihres Textes");
        setValue(L.DESC_COMMAND_INSERT_PART, "Fügt einen neuen Abschnitt der Geschichte zwischen zwei Abschnitten ein; die folgenden Abschnitte bleiben. Parameter: text, part (Handle), before (true oder false).");
        setValue(L.DESC_COMMAND_INSERT_PART_LLM, "Fügt einen neuen Abschnitt mit dem angegebenen Text in die Mitte der Geschichte ein: direkt nach dem Abschnitt `part` (sein Handle) oder direkt davor, wenn `before` true ist. Alles, was auf die Stelle folgte (alle Zweige), folgt jetzt dem neuen Abschnitt, kein Abschnitt wird gelöscht oder neu geschrieben, sodass die Handles, Zusammenfassungen und Daten der anderen Abschnitte bleiben; jeder Abschnitt unterhalb des neuen rückt eine Position nach unten. Verwende es statt die Abschnitte darunter zu löschen und neu anzulegen. Die Zusammenfassungen, die die Stelle abdecken, veralten (wird gemeldet; revalidate-summaries oder regenerate-summary beheben das). Am Ende des Zweigs ist es dasselbe wie create-part. Ändert das Buch. Gibt das Handle des neuen Abschnitts zurück.");
        setValue(L.DESC_COMMAND_INSERT_PART_RETURN, "JSON mit dem neuen Abschnitt (handle, position, words, tokens), wie viele Zweige ihn fortsetzen, der Länge seines Zweigs und den Zusammenfassungen, die veraltet sind");
        setValue(L.DESC_COMMAND_INSERT_ANCHOR_PARAM, "Der Abschnitt, neben dem der neue eingefügt wird (sein Handle): danach oder davor, wenn before true ist");
        setValue(L.DESC_COMMAND_INSERT_BEFORE_PARAM, "true, um vor dem Abschnitt statt danach einzufügen; false, wenn weggelassen");
        setValue(L.DESC_TEMPLATE_PREVIOUS_STORY, "Die Geschichte vor dem Abschnitt, so viel von ihrem Ende, wie hineinpasst (die ältere Geschichte steht in den Zusammenfassungen).");
        setValue(L.DESC_TEMPLATE_PART_TEXT, "Der Text des Abschnitts, der überarbeitet wird.");
        setValue(L.DESC_TEMPLATE_FOLLOWING_STORY, "Die Geschichte nach dem Abschnitt, so viel, wie hineinpasst.");
        setValue(L.DESC_TEMPLATE_REDRAFT_INSTRUCTIONS, "Was der Autor am Abschnitt geändert haben möchte (leer, wenn er keine Anweisungen gegeben hat).");
        setValue(L.DESC_COMMAND_REDRAFT_PART, "Lässt das Modell einen Abschnitt der Geschichte anhand von Anweisungen neu schreiben (jeden Abschnitt, nicht nur den letzten) und ersetzt seinen Text. Kostet Tokens.");
        setValue(L.DESC_COMMAND_REDRAFT_PART_LLM, "Lässt das Modell den Abschnitt `part` (sein Handle) neu schreiben und ersetzt seinen Text durch das Ergebnis; der Abschnitt kann an beliebiger Stelle der Geschichte liegen. `instructions` ist das, was sich ändern soll (\"mehr Dialog hinzufügen\", \"den Kampf verlängern\", \"das Ende beibehalten\"); ohne sie wird der Abschnitt mit denselben Ereignissen neu geschrieben. Das Modell sieht den Abschnitt, die Geschichte davor (ältere Geschichte als Zusammenfassungen) und danach, die Lore, mit der der Abschnitt geschrieben wurde, und die Daten seines Zugs. `prompt` ist ein Überarbeitungsprompt, der statt dem des Buchs verwendet wird (eine Vorlage mit den Variablen text, redraftInstructions, previousStory, summaries, followingStory, backgroundLore, narrativePov, narrativeTense, style, povCharacter, sceneSetting, presentCharacters, instructions); `profile` ein Modellprofil des Agenten, mit dem statt mit dem Modell des Laufs geschrieben wird; `apply` false gibt nur den überarbeiteten Text zurück und lässt den Abschnitt, wie er ist (um ihn erst anzusehen, dann replace-part-text). Ersetzt den Text, daher veralten die Zusammenfassungen, die den Abschnitt abdecken (wird gemeldet). Langsam, kostet Tokens. Gibt den Abschnitt und, bei apply false, den Text zurück.");
        setValue(L.DESC_COMMAND_REDRAFT_PART_RETURN, "JSON-Objekt: das Handle, die Position, die Wörter und die Tokens des Abschnitts, applied, der Text (der gesamte Text, wenn apply false ist) und die veralteten Zusammenfassungen");
        setValue(L.DESC_COMMAND_REDRAFT_INSTRUCTIONS_PARAM, "Was sich im Abschnitt ändern soll; leer schreibt den Abschnitt mit denselben Ereignissen neu");
        setValue(L.DESC_COMMAND_REDRAFT_PROMPT_PARAM, "Ein Überarbeitungsprompt, der statt dem des Buchs verwendet wird (eine Vorlage); leer ist der des Buchs");
        setValue(L.DESC_COMMAND_REDRAFT_APPLY_PARAM, "false gibt nur den überarbeiteten Text zurück und ändert den Abschnitt nicht; true (der Standard) ersetzt den Text des Abschnitts");
        setValue(L.DESC_COMMAND_ANNOTATION_PARAM, "Handle der Anmerkung (das „handle“ von list-annotations)");
        setValue(L.DESC_COMMAND_ANNOTATION_STATUS_FILTER_PARAM, "open (Standard), resolved, dismissed, orphaned oder all");
        setValue(L.DESC_COMMAND_ANNOTATION_STATUS_PARAM, "resolved (Standard), dismissed oder open");
        setValue(L.DESC_COMMAND_ANNOTATION_FILTER_PART_PARAM, "Nur die Anmerkungen dieses Abschnitts: sein Handle oder seine Position im aktiven Zweig (der erste Abschnitt ist 1). Alle Abschnitte, wenn weggelassen");
        setValue(L.DESC_COMMAND_ANNOTATION_TEXT_PARAM, "Die Notiz");
        setValue(L.DESC_COMMAND_ANNOTATION_QUOTE_PARAM, "Die Wörter der Textstelle, auf die sich die Notiz bezieht, aus dem Abschnitt kopiert. Leer für eine Notiz zum ganzen Abschnitt");
        setValue(L.DESC_COMMAND_ANNOTATION_TYPE_PARAM, "Ein freies Wort für die Art der Notiz (Kontinuität, Stil ...), leer für keines");
        setValue(L.DESC_COMMAND_ANNOTATION_SEND_PARAM, "true, um die Notiz zusammen mit dem Abschnitt an das Modell zu geben, false, um das nicht zu tun");
        setValue(L.DESC_COMMAND_LIST_ANNOTATIONS, "Listet die Anmerkungen (Notizen zu Textstellen) des Buchs oder eines Abschnitts auf. Parameter: status, part, offset, limit.");
        setValue(L.DESC_COMMAND_LIST_ANNOTATIONS_LLM, "Listet die Anmerkungen des Buchs auf, Notizen für den Autor, die an einer Textstelle eines Abschnitts (oder an einem ganzen Abschnitt) sitzen. Jede Zeile hat ihr „handle“, das Handle ihres Abschnitts und die Position des Abschnitts, wenn er im aktiven Zweig liegt, den Status (open, resolved, dismissed, orphaned: die Textstelle ist verschwunden), die Quelle (author, ai, agent, plugin), die Art, die Textstelle (Anfangs- und Endoffset im Text des Abschnitts und die zitierten Wörter), wenn sie eine hat, und die Notiz. Der Status ist open, wenn weggelassen, „all“ listet alle auf. Ein Abschnitt (sein Handle oder seine Position im aktiven Zweig) begrenzt die Liste darauf. Nur lesend. Optionen sind positionsbezogen und optional, in der aufgeführten Reihenfolge.");
        setValue(L.DESC_COMMAND_LIST_ANNOTATIONS_RETURN, "JSON mit den Anmerkungen und der Seitenaufteilung");
        setValue(L.DESC_COMMAND_GET_ANNOTATION, "Zeigt eine Anmerkung mit ihrer Notiz und der Textstelle, auf die sie sich bezieht. Parameter: annotation (Handle).");
        setValue(L.DESC_COMMAND_GET_ANNOTATION_LLM, "Eine Anmerkung vollständig: die Notiz, der Status, die Quelle, die Art, die zitierte Textstelle mit etwas Text davor und danach und wo sie im Abschnitt liegt. Die Anmerkung wird über ihr Handle angegeben (aus list-annotations). Nur lesend.");
        setValue(L.DESC_COMMAND_GET_ANNOTATION_RETURN, "JSON mit der Anmerkung");
        setValue(L.DESC_COMMAND_CREATE_ANNOTATION, "Fügt einer Textstelle eines Abschnitts eine Notiz hinzu. Parameter: part (Handle), text, quote, type.");
        setValue(L.DESC_COMMAND_CREATE_ANNOTATION_LLM, "Kommentiert eine Textstelle eines Abschnitts der Geschichte mit einer Notiz für den Autor. Der Text der Geschichte wird nicht geändert, und die Notiz wird nicht an das Modell gesendet. Gib die Wörter der Textstelle als quote an, Buchstabe für Buchstabe kopiert (ein paar Wörter genügen, wenn sie nur einmal im Abschnitt vorkommen): Die Notiz sitzt dann an dieser Textstelle und folgt ihr, wenn der Text bearbeitet wird. Ohne quote betrifft die Notiz den ganzen Abschnitt; auch ein Zitat, das nicht im Text steht, ergibt eine Notiz zum ganzen Abschnitt, und die Antwort sagt das. Die Art ist ein freies Wort (Kontinuität, Stil ...). Der Abschnitt wird über sein Handle angegeben. Fügt den Anmerkungen des Buchs hinzu.");
        setValue(L.DESC_COMMAND_CREATE_ANNOTATION_RETURN, "JSON mit der neuen Anmerkung");
        setValue(L.DESC_COMMAND_UPDATE_ANNOTATION, "Ändert die Notiz, die Art oder das Flag „An Prompt senden“ einer Anmerkung. Parameter: annotation (Handle), text, type, sendToPrompt.");
        setValue(L.DESC_COMMAND_UPDATE_ANNOTATION_LLM, "Ändert eine Anmerkung: den Text der Notiz, ihre Art und ob sie zusammen mit ihrem Abschnitt an das Modell gegeben wird (sendToPrompt). Ein leerer Text oder eine leere Art behält den aktuellen Wert; ein weggelassenes sendToPrompt behält das Flag. Die Anmerkung wird über ihr Handle angegeben (aus list-annotations). Die Textstelle und der Status werden hier nicht geändert (siehe reattach-annotation und resolve-annotation).");
        setValue(L.DESC_COMMAND_UPDATE_ANNOTATION_RETURN, "JSON mit der Anmerkung");
        setValue(L.DESC_COMMAND_RESOLVE_ANNOTATION, "Setzt den Status einer Anmerkung: resolved (Standard), dismissed oder open. Parameter: annotation (Handle), status.");
        setValue(L.DESC_COMMAND_RESOLVE_ANNOTATION_LLM, "Schließt eine Anmerkung als erledigt (das Problem wurde behandelt) oder verworfen (nicht der Mühe wert) oder öffnet sie wieder (open). Eine geschlossene Anmerkung verlässt den Text und bleibt in der Liste. Erledigt, wenn der Status weggelassen wird. Die Anmerkung wird über ihr Handle angegeben (aus list-annotations).");
        setValue(L.DESC_COMMAND_RESOLVE_ANNOTATION_RETURN, "JSON mit der Anmerkung");
        setValue(L.DESC_COMMAND_REATTACH_ANNOTATION, "Heftet eine Anmerkung an die Textstelle, die ein Zitat in ihrem Abschnitt findet. Parameter: annotation (Handle), quote.");
        setValue(L.DESC_COMMAND_REATTACH_ANNOTATION_LLM, "Verschiebt eine Anmerkung an eine andere Textstelle ihres Abschnitts: Die Textstelle wird über das Zitat gefunden, das aus dem Text des Abschnitts kopiert sein muss. Eine verwaiste Anmerkung (ihre Textstelle wurde gelöscht) ist wieder offen. Die Anmerkung wird über ihr Handle angegeben (aus list-annotations). Ohne Zitat betrifft die Anmerkung den ganzen Abschnitt.");
        setValue(L.DESC_COMMAND_REATTACH_ANNOTATION_RETURN, "JSON mit der Anmerkung");
        setValue(L.DESC_COMMAND_DELETE_ANNOTATION, "Löscht eine Anmerkung. Parameter: annotation (Handle).");
        setValue(L.DESC_COMMAND_DELETE_ANNOTATION_LLM, "Löscht eine Anmerkung (der Benutzer kann sie aus dem Papierkorb zurückholen). Um eine Anmerkung zu schließen, sie aber in der Liste zu behalten, verwende resolve-annotation. Die Anmerkung wird über ihr Handle angegeben (aus list-annotations).");
        setValue(L.DESC_COMMAND_DELETE_ANNOTATION_RETURN, "JSON mit dem Handle der gelöschten Anmerkung");
        setValue(L.DESC_TEMPLATE_ANNOTATIONS, "Die offenen Anmerkungen des Abschnitts, je eine Zeile: die Textstelle in Anführungszeichen und die Notiz (leer, wenn sie keine hat).");
        setValue(L.DESC_TEMPLATE_ANNOTATE_INSTRUCTIONS, "Worauf der Autor im Abschnitt achten lassen möchte (leer, wenn er keine Anweisungen gegeben hat).");
        setValue(L.DESC_TEMPLATE_OUTPUT_FORMAT, "Wie dem Modell gesagt wird, seine Antwort zu schreiben; es hängt davon ab, wie die Notizen angefordert werden.");
        setValue(L.DESC_TEMPLATE_STORY_ANNOTATIONS, "Die Notizen des Autors zu Textstellen der Geschichte im Prompt, die dafür markiert sind, an das Modell gegeben zu werden, je eine Zeile (leer, wenn es keine gibt).");
        setValue(L.DESC_TEMPLATE_SELECTION, "Der Text des Abschnitts, den der Autor zum Neuschreiben ausgewählt hat (leer, wenn der ganze Abschnitt überarbeitet wird). Er unterscheidet die Überarbeitung einer Textstelle von der Überarbeitung des ganzen Abschnitts.");
        setValue(L.DESC_TEMPLATE_SELECTION_BEFORE, "Der Text des Abschnitts vor der ausgewählten Textstelle (nur wenn eine Textstelle überarbeitet wird).");
        setValue(L.DESC_TEMPLATE_SELECTION_AFTER, "Der Text des Abschnitts nach der ausgewählten Textstelle (nur wenn eine Textstelle überarbeitet wird).");
        setValue(L.DESC_TEMPLATE_INSTRUCTION_EXAMPLES, "Die Anweisungen, die der Autor für die letzten Abschnitte der Geschichte gegeben hat, die ältesten zuerst (leer, wenn es keine gibt).");
        setValue(L.DESC_TEMPLATE_IMPERSONATE_OUTLINE, "Der Plan der Geschichte, den der Aufrufer angibt, zum Beispiel die Daten des aktuellen Kapitels (leer, wenn keiner).");
        setValue(L.DESC_TEMPLATE_IMPERSONATE_INSTRUCTIONS, "Worum es in den Anweisungen nach dem Wunsch des Autors gehen soll (leer, wenn er keine Vorgabe gemacht hat).");
        setValue(L.DESC_COMMAND_IMPERSONATE, "Lässt das Modell an deiner Stelle die Anweisungen des nächsten Zugs entwerfen und gibt den Text zurück. Kostet Tokens; ändert nichts.");
        setValue(L.DESC_COMMAND_IMPERSONATE_RETURN, "Die entworfenen Anweisungen des nächsten Zugs");
        setValue(L.DESC_COMMAND_IMPERSONATE_INSTRUCTIONS_PARAM, "Worum es in den Anweisungen gehen soll; leer setzt die Geschichte dort fort, wohin sie führt");
        setValue(L.DESC_COMMAND_IMPERSONATE_OUTLINE_PARAM, "Ein Plan der Geschichte für das Modell (zum Beispiel die Daten des aktuellen Kapitels); leer für keinen");
        setValue(L.DESC_COMMAND_IMPERSONATE_PROMPT_PARAM, "Ein Impersonate-Prompt, der statt dem des Buchs verwendet wird (eine Vorlage); leer ist der des Buchs");
        setValue(L.DESC_COMMAND_GENERATE_ANNOTATION, "Lässt das Modell einen Abschnitt der Geschichte prüfen und fügt seine Erkenntnisse als Anmerkungen hinzu. Kostet Tokens.");
        setValue(L.DESC_COMMAND_GENERATE_ANNOTATION_LLM, "Lässt das Modell den Abschnitt `part` (sein Handle; jeder Abschnitt, nicht nur der letzte) prüfen, so wie es der Dialog „Mit KI kommentieren“ tut: Es liest den Abschnitt, die Geschichte davor (ältere Geschichte als Zusammenfassungen) und danach, die Lore und den Stil des Buchs sowie die Notizen, die der Abschnitt schon hat, und findet Kontinuitätsfehler, Widersprüche zur Lore, schwache Passagen und Stilausrutscher. Jede Erkenntnis wird zu einer Anmerkung (Quelle AI) an der vom Modell zitierten Textstelle oder am ganzen Abschnitt, wenn das Zitat nicht im Text steht, und wird sofort hinzugefügt. Der Text der Geschichte wird nicht geändert. `profile` ist ein Modellprofil des Agenten, mit dem statt mit dem Modell des Laufs geprüft wird. Langsam, kostet Tokens. Gibt das Handle des Abschnitts und die neuen Anmerkungen zurück (verwende resolve-annotation, update-annotation oder delete-annotation bei denen, mit denen du nicht einverstanden bist).");
        setValue(L.DESC_COMMAND_GENERATE_ANNOTATION_RETURN, "JSON-Objekt: das Handle des Abschnitts, die Anzahl der erstellten Anmerkungen und die Anmerkungen");
        setValue(L.DESC_COMMAND_INCLUDE_VERSIONS_PARAM, "Auch die älteren Versionen der Abschnitte (ihren Verlauf) durchsuchen; false, wenn weggelassen");
        setValue(L.DESC_COMMAND_SET_BOOK_HISTORY_LIMIT, "Legt fest, wie viele Versionen jedes Abschnitts der Verlauf des Buchs aufbewahrt, oder hebt das Limit des Buchs auf. Parameter: maxVersions.");
        setValue(L.DESC_COMMAND_SET_BOOK_HISTORY_LIMIT_LLM, "Legt die meisten Versionen eines Abschnitts fest, die der Versionsverlauf dieses Buchs aufbewahrt (0 bewahrt ab jetzt keinen Verlauf auf; die vorhandenen Versionen bleiben). Ohne maxVersions wird das Limit des Buchs aufgehoben. Die Limits der Ordner, des Benutzers und des Administrators gelten weiterhin und das strengste gewinnt, das Buch kann sie also nicht erhöhen. Ändert das Buch; löscht keine Version.");
        setValue(L.DESC_COMMAND_SET_BOOK_HISTORY_LIMIT_RETURN, "JSON mit bookLimit (das Limit dieses Buchs, null, wenn es keines hat), effectiveLimit (das Limit, das zählt, null, wenn es keines gibt) und setBy (BOOK, FOLDER, USER, PERMISSION oder NONE)");
        setValue(L.DESC_COMMAND_HISTORY_MAX_VERSIONS_PARAM, "Die meisten aufzubewahrenden Versionen eines Abschnitts; 0 bewahrt keinen Verlauf auf. Lass es weg, um das Limit des Buchs aufzuheben");
        setValue(L.DESC_COMMAND_GET_BOOK_STATISTICS, "Zeigt, was am geöffneten Buch Tag für Tag getan wurde.");
        setValue(L.DESC_COMMAND_GET_BOOK_STATISTICS_LLM, "Was in einem Zeitraum von Tagen am Buch getan wurde, Tag für Tag: gesendete und generierte Tokens, geschriebene, generierte und entfernte Wörter, erstellte und gelöschte Abschnitte, Bearbeitungen, die Minuten, die das Buch geöffnet war, bearbeitet wurde, dafür generiert wurde und Agenten daran gearbeitet haben, und wie sich die Größe des Buchs verändert hat. Der Zeitraum ist ein Name (today, yesterday, last-7-days, last-30-days, this-month, all-time; Standard ist last-7-days), ein Tag (2026-03-14) oder zwei Tage (2026-03-01..2026-03-14); die Seite ist all (der Standard), me oder agents. Nur lesend.");
        setValue(L.DESC_COMMAND_GET_BOOK_STATISTICS_RETURN, "JSON mit den Summen des Zeitraums und einer Zeile für jeden Tag");
        setValue(L.DESC_COMMAND_GET_STATISTICS, "Zeigt, was an allen Büchern getan wurde, nach Tag oder nach Buch.");
        setValue(L.DESC_COMMAND_GET_STATISTICS_LLM, "Was der Autor in einem Zeitraum von Tagen an allen seinen Büchern getan hat: die Summen und eine Zeile für jeden Tag oder jedes Buch (nach Tag, der Standard, oder nach Buch; die Bücher kommen in der Reihenfolge der Wörter, die sie erhalten haben, und haben ein Handle, einen Namen und einen Ordner, auch die Bücher, die es nicht mehr gibt, sind dabei, als deleted markiert). Die Zahlen sind dieselben wie für ein Buch: Tokens, Wörter, Abschnitte, Bearbeitungen, Zeit in Minuten, Wachstum der Größe. Der Zeitraum ist ein Name (today, yesterday, last-7-days, last-30-days, this-month, all-time; Standard ist last-7-days), ein Tag (2026-03-14) oder zwei Tage (2026-03-01..2026-03-14); die Seite ist all (der Standard), me oder agents. Die Minuten der Bücher überschneiden sich, die Summen sind die tatsächliche Zeit. Nur lesend.");
        setValue(L.DESC_COMMAND_GET_STATISTICS_RETURN, "JSON mit den Summen des Zeitraums und einer Zeile für jeden Tag oder jedes Buch");
        setValue(L.DESC_COMMAND_STATISTICS_RANGE_PARAM, "Die Tage: today, yesterday, last-7-days, last-30-days, this-month, all-time, ein Tag (2026-03-14) oder zwei Tage (2026-03-01..2026-03-14)");
        setValue(L.DESC_COMMAND_STATISTICS_SIDE_PARAM, "Wessen Arbeit: all (der Standard), me oder agents");
        setValue(L.DESC_COMMAND_STATISTICS_BY_PARAM, "Wie aufgelistet wird: day (der Standard) oder book");
        setValue(L.DESC_TEMPLATE_EXPORT_AUTHOR, "Autor des Buchs (leer, wenn es keinen gibt).");
        setValue(L.DESC_TEMPLATE_EXPORT_QUOTED_TITLE, "Titel des Buchs, maskiert zur Verwendung in doppelten Anführungszeichen.");
        setValue(L.DESC_TEMPLATE_EXPORT_QUOTED_AUTHOR, "Autor des Buchs, maskiert zur Verwendung in doppelten Anführungszeichen (leer, wenn es keinen gibt).");
        setValue(L.DESC_TEMPLATE_EXPORT_LANGUAGE, "ISO-639-1-Code der Sprache des Buchs.");
        setValue(L.DESC_TEMPLATE_EXPORT_DATE, "Datum des Exports (YYYY-MM-DD).");
        setValue(L.DESC_MACRO_COMMAND, "Führt einen Befehl aus, der nur liest, und fügt seine Antwort ein. Nur für Makros markierte Befehle können verwendet werden, die Antwort bleibt erhalten, bis der Abschnitt neu generiert oder per Variante ersetzt wird.");
        setValue(L.DESC_MACRO_CLOSEST_MESSAGE, "Der Abschnitt der Geschichte, der dem gerade geschriebenen am nächsten liegt; mit einer Zahl der n-t nächste (1 ist der letzte Abschnitt). Leer, wenn es keinen solchen Abschnitt gibt.");
