        setValue(L.DESC_TEMPLATE_FACTS, "Die Fakten, die Erweiterungen über die Geschichte beim Abschnitt kennen, zum Beispiel was jede Figur weiß (leer, wenn keine Erweiterung welche liefert). Prüfe den Abschnitt gegen sie: Ein Widerspruch ist ein Kontinuitätsfehler.");
        setValue(L.DESC_MACRO_EVAL, "true oder false für einen Ausdruck: Vergleiche (== != < <= > >= ~= contains has), verbunden mit and, or, not und Klammern. Ein Text wird in Anführungszeichen geschrieben, ein Name ist ein Wert der Vorlage (povCharacter, presentCharacters, ein Makro ohne Argumente), .name ist eine lokale Variable und $name eine globale. Ein unbekannter Name oder ein Syntaxfehler ergibt Error. == vergleicht exakt (Zahlen nach Wert), ~= ignoriert die Groß-/Kleinschreibung, contains sucht einen Text in einem Text, has sucht ein Element in einer durch Kommas getrennten Liste.");
        setValue(L.DESC_COMMAND_GET_PLANNED_SCENES, "Listet die Szenen des Planers des Buchs mit ihren Details auf und ob sie geschrieben sind.");
        setValue(L.DESC_COMMAND_GET_PLANNED_SCENES_LLM, "Listet die Szenen auf, die der Autor zu schreiben geplant hat, der Reihe nach, mit ihrer Nummer, ihrem Titel, Schauplatz der Szene, der POV-Figur, den anwesenden Figuren, den Anweisungen und ob sie erledigt sind. Lies sie, bevor du Szenen hinzufügst, damit du keine wiederholst.");
        setValue(L.DESC_COMMAND_ADD_PLANNED_SCENE, "Fügt am Ende des Planers eine Szene hinzu.");
        setValue(L.DESC_COMMAND_ADD_PLANNED_SCENE_LLM, "Fügt am Ende des Planers des Autors eine Szene hinzu: einen kurzen Titel und die Zugdetails, die der Autor in das Formular für den neuen Zug eintragen wird, wenn er sie schreibt (Anweisungen, Schauplatz der Szene, POV-Figur, anwesende Figuren). Der Autor sieht sie sofort im Tab „Planer“ und kann sie bearbeiten oder löschen. Schreibe die Anweisungen als Anweisung für das Geschichtsmodell, konkret und kurz; schreibe nicht die Szene selbst.");
        setValue(L.DESC_COMMAND_UPDATE_PLANNED_SCENE, "Ändert den Titel oder die Zugdetails einer geplanten Szene.");
        setValue(L.DESC_COMMAND_UPDATE_PLANNED_SCENE_LLM, "Ändert eine Szene des Planers: Gib nur an, was sich ändern soll, was du weglässt, bleibt. Der Text, den du angibst, ersetzt den alten. Ob die Szene erledigt ist, wird hier nicht geändert, siehe set-planned-scene-done.");
        setValue(L.DESC_COMMAND_SET_PLANNED_SCENE_DONE, "Markiert eine geplante Szene als geschrieben oder nicht geschrieben.");
